-- AI Usage Note
-- Generated by Claude (Claude Code): this migration.
-- How it was verified: applied with prisma migrate reset and prisma migrate deploy; prisma migrate diff against the schema shows no difference; the e2e tests show it rejects names that differ only in case, spaces or the apostrophe.
-- Reviewed by: Daryna Halytska
--
-- Category names are unique once normalized: in lower case, without spaces at the ends, with runs of spaces as
-- one, and with every apostrophe (' ʼ ’) as ʼ. PrismaCategoriesRepository checks names with the same expression.
-- Prisma does not manage this index; it is not in schema.prisma.
CREATE UNIQUE INDEX "categories_name_normalized_key" ON "categories" (
    lower(btrim(regexp_replace(regexp_replace("name", '[[:space:]]+', ' ', 'g'), '[''ʼ’]', 'ʼ', 'g')))
);
